:root {
  --primary: #312e81; /* Deep Indigo */
  --primary-light: #4f46e5;
  --accent: #10b981; /* Emerald/Bright Green */
  --accent-light: #d1fae5;
  --lime: #E6FF32;
  --text-main: #111827;
  --text-muted: #4b5563;
  --bg-page: #ffffff;
  --bg-alt: #f3f4f6;
  --bg-card: #ffffff;
  --border: #e5e7eb;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius: 12px;
  --radius-lg: 24px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', sans-serif;
  color: var(--text-main);
  background-color: var(--bg-page);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6, .font-heading {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 700;
  color: var(--primary);
  line-height: 1.2;
}

h1 { font-size: 3.5rem; letter-spacing: -0.02em; }
h2 { font-size: 2.5rem; letter-spacing: -0.01em; margin-bottom: 1.5rem; }
h3 { font-size: 1.5rem; margin-bottom: 1rem; }

p { margin-bottom: 1rem; color: var(--text-muted); }
a { color: var(--primary-light); text-decoration: none; transition: 0.2s; }
a:hover { color: var(--primary); }
ul { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Typography utilities */
.text-center { text-align: center; }
.text-muted { color: var(--text-muted); }
.text-primary { color: var(--primary); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: 9999px;
  font-weight: 600;
  font-family: 'Inter', sans-serif;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 2px solid transparent;
}
.btn-primary {
  background-color: var(--accent);
  color: #fff;
  box-shadow: 0 4px 14px 0 rgba(16, 185, 129, 0.39);
}
.btn-primary:hover {
  background-color: #059669;
  transform: translateY(-2px);
  color: #fff;
}
.btn-outline {
  border-color: var(--primary);
  color: var(--primary);
}
.btn-outline:hover {
  background-color: var(--primary);
  color: #fff;
}

/* Layout */
section {
  padding: 6rem 0;
}
.section-alt {
  background-color: var(--bg-alt);
}
.grid {
  display: grid;
  gap: 2rem;
}
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }

/* Navbar */
.navbar {
  position: sticky;
  top: 0;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  z-index: 50;
  padding: 1rem 0;
}
.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800;
  font-size: 1.5rem;
  color: var(--primary);
}
.nav-links ul {
  display: flex;
  gap: 2rem;
}
.nav-links a {
  font-weight: 500;
  color: var(--text-main);
}
.nav-links a:hover, .nav-links a.active {
  color: var(--primary-light);
}
.nav-cta {
  display: flex;
  gap: 1rem;
}
.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
}

/* Hero */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: white;
}
.hero h1, .hero p {
  color: white;
}
.hero p {
  font-size: 1.25rem;
  max-width: 800px;
  margin: 0 auto 2rem;
  opacity: 0.9;
}
.hero-cta {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-bottom: 4rem;
}
.hero-cta .btn-outline {
  border-color: white;
  color: white;
}
.hero-cta .btn-outline:hover {
  background-color: white;
  color: var(--primary);
}

/* Tab Switcher in Hero */
.hero-preview {
  margin-top: 3rem;
  position: relative;
  max-width: 1000px;
  margin-left: auto;
  margin-right: auto;
}
.hero-tabs {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}
.hero-tab-btn {
  background: rgba(255,255,255,0.2);
  border: 1px solid rgba(255,255,255,0.3);
  color: white;
  padding: 0.5rem 1.5rem;
  border-radius: 9999px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.3s;
}
.hero-tab-btn.active, .hero-tab-btn:hover {
  background: white;
  color: var(--primary);
}
.hero-view-container {
  background: white;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  aspect-ratio: 16/9;
  position: relative;
}
.hero-view {
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--primary);
  font-weight: 700;
  font-size: 1.5rem;
}
.hero-view.active {
  opacity: 1;
  pointer-events: auto;
}
.hero-view.creator { background: #f8fafc; }
.hero-view.student { background: #f0fdf4; }

/* Stats Bar */
.stats-bar {
  padding: 4rem 0;
  border-bottom: 1px solid var(--border);
}
.stat-item {
  text-align: center;
}
.stat-number {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--primary);
  font-family: 'Plus Jakarta Sans', sans-serif;
  margin-bottom: 0.5rem;
}
.stat-label {
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-muted);
}

/* Cards */
.card {
  background: var(--bg-card);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-lg);
}
.card-icon {
  width: 48px;
  height: 48px;
  background: var(--accent-light);
  color: var(--accent);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
}

/* Interactive Tabs (Why Choose Us) */
.feature-tabs-container {
  display: flex;
  gap: 3rem;
  align-items: flex-start;
}
.feature-tabs-nav {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex: 1;
}
.feature-tab {
  text-align: left;
  padding: 1rem 1.5rem;
  border-radius: var(--radius);
  background: none;
  border: 1px solid transparent;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.2s;
}
.feature-tab:hover {
  background: var(--bg-alt);
}
.feature-tab.active {
  background: white;
  border-color: var(--border);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}
.feature-tabs-content {
  flex: 2;
  background: white;
  padding: 3rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border);
}
.feature-pane {
  display: none;
}
.feature-pane.active {
  display: block;
  animation: fadeIn 0.4s ease forwards;
}
.feature-pane ul {
  margin-top: 1.5rem;
}
.feature-pane li {
  margin-bottom: 0.75rem;
  padding-left: 1.5rem;
  position: relative;
}
.feature-pane li::before {
  content: "→";
  position: absolute;
  left: 0;
  color: var(--accent);
  font-weight: bold;
}

/* Testimonials Carousel */
.carousel-wrapper {
  position: relative;
  overflow: hidden;
  padding: 2rem 0;
}
.carousel-track {
  display: flex;
  gap: 2rem;
  transition: transform 0.5s ease-in-out;
}
.carousel-item {
  flex: 0 0 calc(100% / 3 - 1.33rem);
  min-width: calc(100% / 3 - 1.33rem);
}
.testimonial-card {
  height: 100%;
  display: flex;
  flex-direction: column;
}
.testimonial-card .quote {
  font-size: 1.125rem;
  font-style: italic;
  margin-bottom: 2rem;
  flex-grow: 1;
}
.testimonial-author {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.author-avatar {
  width: 50px; height: 50px; border-radius: 50%; background: var(--border);
}
.author-info h4 { margin: 0; font-size: 1rem; }
.author-info p { margin: 0; font-size: 0.875rem; color: var(--text-muted); }
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-btn:hover {
  background: var(--bg-alt);
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 2rem;
  align-items: center;
  justify-items: center;
}
.integration-item {
  filter: grayscale(100%) opacity(0.6);
  transition: 0.3s;
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--text-muted);
}
.integration-item:hover {
  filter: none;
  color: var(--primary);
}

/* FAQ Accordion */
.faq-container {
  max-width: 800px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1.5rem 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-main);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-icon {
  transition: transform 0.3s ease;
}
.faq-question.active .faq-icon {
  transform: rotate(180deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}
.faq-answer p {
  padding-bottom: 1.5rem;
}

/* Footer */
.footer {
  background-color: var(--text-main);
  color: white;
  padding: 6rem 0 2rem;
}
.footer p, .footer a {
  color: #9ca3af;
}
.footer h3 {
  color: white;
  font-size: 1.125rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 4rem;
  margin-bottom: 4rem;
}
.footer .logo {
  color: white;
}
.footer-col ul li {
  margin-bottom: 0.75rem;
}
.footer-col ul li a:hover {
  color: white;
}
.footer-bottom {
  border-top: 1px solid #374151;
  padding-top: 2rem;
  text-align: center;
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-on-scroll {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}
.animate-on-scroll.is-visible {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive */
@media (max-width: 992px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .feature-tabs-container { flex-direction: column; }
  .feature-tabs-nav { flex-direction: row; flex-wrap: wrap; }
  .carousel-item { flex: 0 0 calc(100% / 2 - 1rem); min-width: calc(100% / 2 - 1rem); }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .brand-col { grid-column: 1 / -1; }
}

@media (max-width: 768px) {
  .nav-links, .nav-cta { display: none; }
  .mobile-menu-toggle { display: block; }
  .grid-2 { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2.5rem; }
  .carousel-item { flex: 0 0 100%; min-width: 100%; }
  .stats-bar .grid-3 { grid-template-columns: 1fr; gap: 2rem; }
}
